<?php

namespace App\Console\Commands;

use App\Enums\Locale;
use App\Support\I18n\FrontendTranslations;
use Illuminate\Console\Attributes\Description;
use Illuminate\Console\Attributes\Signature;
use Illuminate\Console\Command;
use Illuminate\Filesystem\Filesystem;

/**
 * Generates a TypeScript union of every UI translation key so that t('...') is type-checked.
 *
 * The fallback locale is the source of truth for the key list; the parity test guarantees
 * the other locales have exactly the same keys.
 */
#[Signature('i18n:types {--check : Fail if the generated file is out of date instead of writing it}')]
#[Description('Generate TypeScript types for the frontend translation keys')]
class GenerateTranslationTypes extends Command
{
    public const OUTPUT = 'resources/js/types/translation-keys.ts';

    public function handle(FrontendTranslations $translations, Filesystem $files): int
    {
        $contents = self::render(array_keys($translations->load(Locale::fallback())));
        $path = base_path(self::OUTPUT);

        if ($this->option('check')) {
            if (! $files->exists($path) || $files->get($path) !== $contents) {
                $this->components->error('Translation types are out of date. Run `php artisan i18n:types`.');

                return self::FAILURE;
            }

            $this->components->info('Translation types are up to date.');

            return self::SUCCESS;
        }

        $files->put($path, $contents);
        $this->components->info('Wrote '.self::OUTPUT);

        return self::SUCCESS;
    }

    /**
     * @param  list<string>  $keys
     */
    public static function render(array $keys): string
    {
        sort($keys);

        $union = $keys === []
            ? '    never'
            : implode("\n", array_map(static fn (string $key): string => "    | '".addcslashes($key, "'\\")."'", $keys));

        return <<<TS
            // This file is generated by `php artisan i18n:types`. Do not edit it by hand.
            // Source of truth: lang/{locale}/ui/*.php

            export type TranslationKey =
            {$union};

            TS;
    }
}
